contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs: depositAmount to deposit into c, and collectAmount to attempt to collect.
    // Both are amounts in wei. This function will fund itself to send depositAmount.
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure starting observed balances for this test caller (InvMutTest) on contract c.
        uint beforeCallerBal = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // Make a deposit into c from this contract
        c.Deposit{value: depositAmount}();

        // Read balances after deposit
        uint afterDepositCallerBal = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // Sanity: deposit should increase both by the depositAmount (checked via assert variable later)
        // Now attempt to Collect collectAmount and record whether it reverted.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final balances
        uint finalCallerBal = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // The general rule we assert:
        // If Collect did NOT revert, then final recorded caller balance decreased by exactly collectAmount
        // relative to the balance immediately before the Collect call, and the contract's Ether balance
        // also decreased by exactly collectAmount. If Collect reverted, no guarantee is asserted here.
        assert(
            reverted || (
                // afterDepositCallerBal >= collectAmount must hold for Collect to succeed according to contract logic
                afterDepositCallerBal >= collectAmount
                && finalCallerBal + collectAmount == afterDepositCallerBal
                && finalContractEth + collectAmount == afterDepositContractEth
            )
        );
    }

    // Allow contract to receive Ether so it can fund deposits and accept refunds from c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs: depositAmount to fund a Deposit into c, and collectAmount to attempt to Collect.
    // The test contract must hold enough Ether to send depositAmount.
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Observe initial recorded balance for this contract and contract Ether balance
        uint beforeBal = c.balances(address(this));
        uint beforeEth = address(c).balance;

        // Make a deposit so the caller may be able to Collect
        c.Deposit{value: depositAmount}();

        // Observe balances immediately before attempting Collect
        uint midBal = c.balances(address(this));
        uint midEth = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final balances
        uint afterBal = c.balances(address(this));
        uint afterEth = address(c).balance;

        // General rule asserted for all inputs:
        // If Collect did not revert, then recorded balance decreased by exactly collectAmount
        // (relative to the balance immediately before Collect), and the contract's Ether balance did not increase
        // (i.e. afterEth <= midEth). This allows for the case where a failed send would revert the whole call
        // (so we only require the relation when Collect returned normally).
        assert(reverted || (midBal >= collectAmount && afterBal + collectAmount == midBal && afterEth <= midEth));
    }

    // Allow receiving Ether back from c when Collect succeeds
    receive() external payable {}
}

