contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to cause a Collect and check the observable invariants when it does NOT revert.
    // params: depositor will deposit `depositAmt`, then we try to Collect amount `collectAmt`.
    function run(address depositor, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // Ensure we operate as the depositor: calls from this contract are from address(this).
        // So depositor param is not used to control msg.sender; instead depositor is only recorded in asserts.
        // First, deposit depositAmt into c from this contract so balances[this] increases.
        uint beforeContractBalance = address(c).balance;
        uint beforeRecorded = c.balances(address(this));

        // perform deposit (may revert only if arithmetic overflow, but we allow any inputs)
        c.Deposit{value: depositAmt}();

        uint afterContractBalance = address(c).balance;
        uint afterRecorded = c.balances(address(this));

        // Now attempt to Collect collectAmt; capture whether it reverted.
        bool reverted;
        uint beforeRecordedForCollect = afterRecorded;
        uint beforeContractBalanceForCollect = afterContractBalance;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalRecorded = c.balances(address(this));
        uint finalContractBalance = address(c).balance;

        // General rule asserted when Collect did NOT revert:
        // - The recorded balance must have decreased by exactly collectAmt (i.e., finalRecorded + collectAmt == beforeRecordedForCollect)
        // - The contract's Ether balance must have decreased by at least collectAmt (finalContractBalance + collectAmt <= beforeContractBalanceForCollect)
        // We express both in a single assert. This is observable without accessing Log internals.
        assert( reverted || ( finalRecorded + collectAmt == beforeRecordedForCollect && finalContractBalance + collectAmt <= beforeContractBalanceForCollect ) );
    }

    // accept Ether so c.call can send to us during Collect
    receive() external payable { }
}

