contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be checked for all inputs
    function run(uint depositAmount, uint collectAmount, address payable other) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        // Ensure other is not zero to allow sending logs etc. (not strictly necessary)
        require(other != address(0), "other must be nonzero");

        // 1) Make a deposit into c from this contract to set up balances
        // Use Deposit() which is payable and will log. This is a state-changing call and must be top-level.
        c.Deposit{value: depositAmount}();

        // Read observable state before attempting Collect
        uint beforeBalance = c.balances(address(this));
        uint contractBalanceBefore = address(c).balance;
        uint minSum = c.MinSum();

        // 2) Try Collect; capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after call
        uint afterBalance = c.balances(address(this));
        uint contractBalanceAfter = address(c).balance;

        // The general property to assert:
        // - If Collect did not revert then:
        //     * beforeBalance >= minSum AND beforeBalance >= collectAmount (these are required by Collect's if)
        //     * afterBalance == beforeBalance - collectAmount (recorded balance decreases by collected amount)
        //     * contractBalanceAfter <= contractBalanceBefore - collectAmount (contract ether decreased by at least collected amount)
        // - If Collect reverted then either the preconditions were not met (so at least one of the inequalities is false)

        assert(
            (!reverted && beforeBalance >= minSum && beforeBalance >= collectAmount && afterBalance == beforeBalance - collectAmount && contractBalanceAfter + collectAmount <= contractBalanceBefore)
            || (reverted && (beforeBalance < minSum || beforeBalance < collectAmount))
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}
